3	import { canonical, parseExact, type Json, utf8Compare } from "./exact-json.js";
4	type ObjectValue = { [key: string]: Json };
5	const object = (v: Json | undefined): v is ObjectValue => v !== null && typeof v === "object" && !Array.isArray(v);
6	const equal = (a: Json, b: Json): boolean => {
7	  if (typeof a !== typeof b) return false;
8	  if (a === b) return true;
9	  if (Array.isArray(a)) return Array.isArray(b) && a.length === b.length && a.every((v, i) => equal(v, b[i]!));
10	  if (!object(a) || !object(b)) return false;
11	  const keys = Object.keys(a);
12	  return keys.length === Object.keys(b).length && keys.every(k => Object.hasOwn(b, k) && equal(a[k]!, b[k]!));
13	};
