28	  private readonly patterns = new Map<string, RegExp>();
29	  private readonly checkedRefs = new Set<string>();
30	  constructor(documents: readonly Json[]) {
31	    for (const document of documents) {
32	      const owned = parseExact(canonical(document));
33	      if (!object(owned) || typeof owned.$id !== "string" || this.documents.has(owned.$id)) throw new SchemaError("duplicate or missing schema ID");
