37	  }
38	  private regex(pattern: string): RegExp {
39	    let result = this.patterns.get(pattern);
40	    if (!result) {
41	      const translated = selectedPattern(pattern);
42	      if (translated === undefined) throw new SchemaError("pattern outside selected profile");
43	      result = new RegExp(translated, "u"); this.patterns.set(pattern, result);
44	    }
45	    return result;
46	  }
47	  private resolve(ref: string, owner: string): [Json, string] {
48	    const split = ref.indexOf("#");
49	    const id = (split < 0 ? ref : ref.slice(0, split)) || owner;
50	    const fragment = split < 0 ? "" : ref.slice(split + 1);
51	    let value = this.documents.get(id);
52	    if (value === undefined) throw new SchemaError("unregistered schema ID: " + id);
53	    if (fragment && !fragment.startsWith("/")) throw new SchemaError("unsupported reference anchor");
