98	        }
99	        if (key === "x-opensip-order") {
100	          const named = new Set(["sequence", "utf8", "canonical-set", "canonical-order", "path", "ruleId", "waiverId", "predicate", "numeric", "ordinal", "candidateOrdinal"]);
