102	          if (!(typeof value === "string" && named.has(value)) && !(object(value) && Object.keys(value).length === 1 && Array.isArray(by) && by.length > 0 && by.every(k => typeof k === "string" && k.length > 0) && new Set(by).size === by.length)) throw new SchemaError("unsupported ordering annotation");
103	        }
104	        if (key === "pattern") this.regex(value as string);
105	        if (key === "patternProperties") for (const pattern of Object.keys(value as ObjectValue)) this.regex(pattern);
106	      }
107	    };
