118	    const bound = (length: number, schema: ObjectValue, low: string, high: string): boolean =>
119	      (schema[low] === undefined || BigInt(length) >= (schema[low] as bigint)) &&
120	      (schema[high] === undefined || BigInt(length) <= (schema[high] as bigint));
