122	      if (++callDepth > 256) throw new ShapeLimit("schema call-depth limit");
123	      try { return evaluate(schema, item, owner); }
124	      finally { callDepth--; }
125	    };
126	    const evaluate = (schema: Json, item: Json, owner: string): boolean => {
127	      spend();
