144	      if (schema.not !== undefined && check(schema.not, item, owner)) return false;
145	      if (schema.if !== undefined) {
146	        const branch = check(schema.if, item, owner) ? schema.then : schema.else;
147	        if (branch !== undefined && !check(branch, item, owner)) return false;
148	      }
149	      if (typeof item === "bigint" && ((schema.minimum !== undefined && item < (schema.minimum as bigint)) || (schema.maximum !== undefined && item > (schema.maximum as bigint)))) return false;
