152	        if (typeof schema.pattern === "string" && !this.regex(schema.pattern).test(item)) return false;
153	      }
154	      if (Array.isArray(item)) {
155	        if (!bound(item.length, schema, "minItems", "maxItems")) return false;
156	        if (schema.items !== undefined && !item.every(v => check(schema.items!, v, owner))) return false;
157	        if (schema.contains !== undefined && !item.some(v => check(schema.contains!, v, owner))) return false;
158	        if (schema.uniqueItems === true) {
159	          const seen = new Set<string>();
160	          for (const v of item) { spend(); const key = new TextDecoder().decode(canonical(v)); if (seen.has(key)) return false; seen.add(key); }
