162	        const order = schema["x-opensip-order"];
163	        if (order !== undefined && order !== "sequence" && !ordered(item, order)) return false;
164	      }
165	      if (object(item)) {
166	        const keys = Object.keys(item);
167	        if (!bound(keys.length, schema, "minProperties", "maxProperties")) return false;
168	        if (Array.isArray(schema.required) && !schema.required.every(k => typeof k === "string" && Object.hasOwn(item, k))) return false;
169	        for (const key of keys) {
170	          spend(); const child = item[key]!; let matched = false;
171	          if (schema.propertyNames !== undefined && !check(schema.propertyNames, key, owner)) return false;
172	          if (object(schema.properties) && Object.hasOwn(schema.properties, key)) { matched = true; if (!check(schema.properties[key]!, child, owner)) return false; }
