175	          }
176	          if (!matched && schema.additionalProperties !== undefined && !check(schema.additionalProperties, child, owner)) return false;
177	        }
178	      }
179	      return true;
180	    };
181	    const [schema, owner] = this.resolve(ref, "");
182	    return check(schema, owned, owner);
183	  }
