186	function ordered(items: Json[], order: Json): boolean {
187	  const compare = (a: string | bigint, b: string | bigint): number =>
188	    typeof a === "string" && typeof b === "string" ? utf8Compare(a, b) : a < b ? -1 : a > b ? 1 : 0;
189	  let keys: (string | bigint)[][] = [];
190	  const numeric = order === "numeric" || order === "ordinal" || order === "candidateOrdinal";
191	  const fields = object(order) ? order.by : order === "predicate" ? ["ruleId", "subjectId", "predicateId"] : [order];
192	  for (const item of items) {
193	    let key: Json[];
194	    if (order === "utf8" || order === "numeric") key = [item];
195	    else if (order === "canonical-set" || order === "canonical-order") key = [new TextDecoder().decode(canonical(item))];
196	    else {
197	      if (!object(item) || !Array.isArray(fields) || fields.some(k => typeof k !== "string" || !Object.hasOwn(item, k))) return false;
198	      key = fields.map(k => item[k as string]!);
199	    }
200	    if (!key.every(v => typeof v === (numeric ? "bigint" : "string"))) return false;
201	    keys.push(key as (string | bigint)[]);
202	  }
203	  if (order === "ordinal" && !keys.every((k, i) => k[0] === BigInt(i))) return false;
204	  for (let i = 1; i < keys.length; i++) {
205	    const a = keys[i - 1]!, b = keys[i]!;
206	    let c = 0;
207	    for (let j = 0; j < a.length && c === 0; j++) c = compare(a[j]!, b[j]!);
208	    if (c > 0 || (c === 0 && order !== "canonical-order")) return false;
209	  }
210	  return true;
211	}
