1	/** Trial exact JSON codec: inert values, no semantic admission authority. */
2	export type Json = null | boolean | bigint | string | Json[] | { [key: string]: Json };
3	export const MAX_BYTES = 4 * 1024 * 1024;
4	export const MAX_DEPTH = 32;
5	const MIN_INTEGER = -(1n << 63n);
6	const MAX_INTEGER = (1n << 64n) - 1n;
7	const encoder = new TextEncoder();
8	export class JsonError extends Error {}
9	const fail = (message: string): never => { throw new JsonError(message); };
10	
11	function scalarString(value: string): void {
12	  for (const ch of value) {
13	    const cp = ch.codePointAt(0)!;
14	    if (cp >= 0xd800 && cp <= 0xdfff) fail("UNICODE_SCALAR_REQUIRED");
15	  }
16	}
17	
18	export function utf8Compare(a: string, b: string): number {
19	  const left = encoder.encode(a), right = encoder.encode(b);
20	  for (let i = 0; i < Math.min(left.length, right.length); i++) {
21	    if (left[i] !== right[i]) return left[i]! < right[i]! ? -1 : 1;
22	  }
23	  return left.length - right.length;
24	}
