26	export function parseExact(raw: Uint8Array): Json {
27	  if (!(raw instanceof Uint8Array)) fail("BYTE_INPUT_REQUIRED");
28	  if (typeof SharedArrayBuffer !== "undefined" && raw.buffer instanceof SharedArrayBuffer) fail("SHARED_BYTES_FORBIDDEN");
29	  if (raw.length > MAX_BYTES) fail("BYTE_LIMIT");
30	  let text: string;
31	  try { text = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(raw); }
32	  catch { return fail("INVALID_UTF8"); }
33	  let offset = 0;
34	  const space = () => { while (offset < text.length && " \t\r\n".includes(text[offset]!)) offset++; };
35	  const string = (): string => {
36	    const start = offset++;
37	    let escaped = false;
38	    while (offset < text.length) {
39	      const ch = text[offset++]!;
40	      if (!escaped && ch === '"') {
41	        let value: string;
42	        try { value = JSON.parse(text.slice(start, offset)) as string; }
43	        catch { return fail("INVALID_STRING"); }
44	        scalarString(value);
45	        return value;
46	      }
47	      if (escaped) escaped = false;
48	      else if (ch === "\\") escaped = true;
49	    }
50	    return fail("UNTERMINATED_STRING");
51	  };
52	  const value = (depth: number): Json => {
53	    space();
54	    const ch = text[offset];
55	    if (ch === '"') return string();
56	    if (ch === "[" || ch === "{") {
57	      if (depth >= MAX_DEPTH) fail("DEPTH_LIMIT");
58	      offset++; space();
59	      if (ch === "[") {
60	        const result: Json[] = [];
61	        if (text[offset] === "]") { offset++; return result; }
62	        while (true) {
63	          result.push(value(depth + 1)); space();
64	          if (text[offset] === "]") { offset++; return result; }
65	          if (text[offset++] !== ",") return fail("ARRAY_DELIMITER");
66	        }
67	      }
68	      const result: { [key: string]: Json } = Object.create(null);
69	      if (text[offset] === "}") { offset++; return result; }
70	      while (true) {
71	        space(); if (text[offset] !== '"') return fail("OBJECT_KEY");
72	        const key = string();
73	        if (Object.hasOwn(result, key)) fail("DUPLICATE_KEY");
74	        space(); if (text[offset++] !== ":") return fail("OBJECT_COLON");
75	        result[key] = value(depth + 1); space();
76	        if (text[offset] === "}") { offset++; return result; }
77	        if (text[offset++] !== ",") return fail("OBJECT_DELIMITER");
78	      }
79	    }
80	    for (const [token, result] of [["true", true], ["false", false], ["null", null]] as const) {
81	      if (text.startsWith(token, offset)) { offset += token.length; return result; }
82	    }
83	    const match = /^-?(?:0|[1-9][0-9]*)/.exec(text.slice(offset));
84	    if (!match) return fail("INVALID_VALUE");
85	    const lexeme = match[0]; offset += lexeme.length;
86	    if (lexeme === "-0") fail("NEGATIVE_ZERO");
87	    if (text[offset] === "." || text[offset] === "e" || text[offset] === "E") fail("FLOAT_FORBIDDEN");
88	    // Reject overlong digits before allocating an unbounded BigInt.
89	    if (lexeme.length > 21) fail("INTEGER_RANGE");
90	    const number = BigInt(lexeme);
91	    if (number < MIN_INTEGER || number > MAX_INTEGER) fail("INTEGER_RANGE");
92	    return number;
93	  };
94	  const result = value(0); space();
95	  if (offset !== text.length) fail("TRAILING_DATA");
96	  return result;
97	}
