99	export function canonical(value: Json): Uint8Array {
100	  const chunks: string[] = []; let bytes = 0;
101	  const put = (part: string) => {
102	    bytes += encoder.encode(part).length;
103	    if (bytes > MAX_BYTES) fail("BYTE_LIMIT");
104	    chunks.push(part);
105	  };
106	  const visit = (item: Json, depth: number): void => {
107	    if (item === null) { put("null"); return; }
108	    if (typeof item === "boolean") { put(item ? "true" : "false"); return; }
109	    if (typeof item === "bigint") {
110	      if (item < MIN_INTEGER || item > MAX_INTEGER) fail("INTEGER_RANGE");
111	      put(item.toString()); return;
112	    }
113	    if (typeof item === "string") { scalarString(item); put(JSON.stringify(item)); return; }
114	    if (typeof item !== "object") fail("EXACT_JSON_TYPE_REQUIRED");
115	    if (depth >= MAX_DEPTH) fail("DEPTH_LIMIT");
116	    if (Array.isArray(item)) {
117	      if (Object.getPrototypeOf(item) !== Array.prototype) fail("PLAIN_ARRAY_REQUIRED");
118	      if (Object.getOwnPropertySymbols(item).length || Object.getOwnPropertyNames(item).length !== item.length + 1) fail("PLAIN_ARRAY_REQUIRED");
119	      put("["); for (let i = 0; i < item.length; i++) {
120	        if (i) put(",");
121	        const descriptor = Object.getOwnPropertyDescriptor(item, String(i));
122	        if (!descriptor || !Object.hasOwn(descriptor, "value")) fail("ARRAY_DATA_PROPERTIES_REQUIRED");
123	        visit(descriptor!.value as Json, depth + 1);
124	      } put("]");
125	      return;
126	    }
127	    if (Object.getPrototypeOf(item) !== null && Object.getPrototypeOf(item) !== Object.prototype) fail("PLAIN_OBJECT_REQUIRED");
128	    if (Object.getOwnPropertySymbols(item).length) fail("STRING_KEY_REQUIRED");
129	    const keys = Object.keys(item).sort(utf8Compare);
130	    if (keys.length !== Object.getOwnPropertyNames(item).length) fail("ENUMERABLE_DATA_REQUIRED");
131	    put("{"); for (let i = 0; i < keys.length; i++) {
132	      if (i) put(","); const key = keys[i]!; scalarString(key);
133	      const descriptor = Object.getOwnPropertyDescriptor(item, key)!;
134	      if (!Object.hasOwn(descriptor, "value")) fail("DATA_PROPERTIES_REQUIRED");
135	      put(JSON.stringify(key)); put(":"); visit(descriptor.value as Json, depth + 1);
136	    } put("}");
137	  };
138	  visit(value, 0); return encoder.encode(chunks.join(""));
139	}
